CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" character varying(50) NOT NULL,
    "PasswordHash" character varying(500) NOT NULL,
    "Name" character varying(100) NOT NULL,
    "Email" character varying(100) NOT NULL,
    "Phone" character varying(20) NOT NULL,
    "Role" character varying(50) NOT NULL DEFAULT ('user'),
    "ProfilePictureUrl" text,
    "Bio" text,
    "Address" text,
    "City" text,
    "State" text,
    "ZipCode" text,
    "Country" text,
    "IsEmailVerified" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "LastLoginAt" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "Cues" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(200) NOT NULL,
    "Brand" character varying(100) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "Price" numeric(10,2) NOT NULL,
    "CueType" character varying(50) NOT NULL,
    "Weight" numeric,
    "Length" numeric,
    "TipSize" numeric,
    "ShaftMaterial" text,
    "WrapMaterial" text,
    "ManufactureYear" integer,
    "Condition" character varying(50) NOT NULL,
    "Location" character varying(200) NOT NULL,
    "IsSold" boolean NOT NULL,
    "SoldDate" timestamp with time zone,
    "UserId" integer NOT NULL,
    "ViewCount" integer NOT NULL,
    "AverageRating" numeric NOT NULL,
    "RatingCount" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    CONSTRAINT "PK_Cues" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Cues_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CueImages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CueId" integer NOT NULL,
    "ImageUrl" character varying(500) NOT NULL,
    "AltText" character varying(200),
    "DisplayOrder" integer NOT NULL,
    "IsPrimary" boolean NOT NULL,
    "UploadedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    CONSTRAINT "PK_CueImages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CueImages_Cues_CueId" FOREIGN KEY ("CueId") REFERENCES "Cues" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Messages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SenderId" integer NOT NULL,
    "RecipientId" integer NOT NULL,
    "CueId" integer,
    "Subject" character varying(200) NOT NULL,
    "Content" character varying(4000) NOT NULL,
    "IsRead" boolean NOT NULL,
    "ReadAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "MessageType" character varying(50) NOT NULL,
    CONSTRAINT "PK_Messages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Messages_Cues_CueId" FOREIGN KEY ("CueId") REFERENCES "Cues" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Messages_Users_RecipientId" FOREIGN KEY ("RecipientId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Messages_Users_SenderId" FOREIGN KEY ("SenderId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Ratings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CueId" integer NOT NULL,
    "RatedByUserId" integer NOT NULL,
    "SellerUserId" integer NOT NULL,
    "RatingValue" integer NOT NULL DEFAULT 0,
    "ReviewText" text,
    "Category" character varying(50),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    CONSTRAINT "PK_Ratings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Ratings_Cues_CueId" FOREIGN KEY ("CueId") REFERENCES "Cues" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Ratings_Users_RatedByUserId" FOREIGN KEY ("RatedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Ratings_Users_SellerUserId" FOREIGN KEY ("SellerUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SavedCues" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CueId" integer NOT NULL,
    "SavedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "Note" text,
    CONSTRAINT "PK_SavedCues" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SavedCues_Cues_CueId" FOREIGN KEY ("CueId") REFERENCES "Cues" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_SavedCues_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Transactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CueId" integer NOT NULL,
    "SellerId" integer NOT NULL,
    "BuyerId" integer NOT NULL,
    "SalePrice" numeric(10,2) NOT NULL,
    "Status" character varying(50) NOT NULL,
    "ShippingMethod" character varying(100) NOT NULL,
    "ShippingCost" numeric(10,2),
    "PaymentMethod" character varying(100) NOT NULL,
    "TransactionNumber" character varying(100) NOT NULL,
    "Notes" text,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "CompletedAt" timestamp with time zone,
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    CONSTRAINT "PK_Transactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Transactions_Cues_CueId" FOREIGN KEY ("CueId") REFERENCES "Cues" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Transactions_Users_BuyerId" FOREIGN KEY ("BuyerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Transactions_Users_SellerId" FOREIGN KEY ("SellerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_CueImage_CueId" ON "CueImages" ("CueId");

CREATE INDEX "IX_Cue_Brand_Type" ON "Cues" ("Brand", "CueType");

CREATE INDEX "IX_Cue_IsSold" ON "Cues" ("IsSold");

CREATE INDEX "IX_Cue_UserId" ON "Cues" ("UserId");

CREATE INDEX "IX_Message_IsRead" ON "Messages" ("IsRead");

CREATE INDEX "IX_Message_Sender_Recipient" ON "Messages" ("SenderId", "RecipientId");

CREATE INDEX "IX_Messages_CueId" ON "Messages" ("CueId");

CREATE INDEX "IX_Messages_RecipientId" ON "Messages" ("RecipientId");

CREATE UNIQUE INDEX "IX_Rating_Unique_User_Cue" ON "Ratings" ("CueId", "RatedByUserId");

CREATE INDEX "IX_Ratings_RatedByUserId" ON "Ratings" ("RatedByUserId");

CREATE INDEX "IX_Ratings_SellerUserId" ON "Ratings" ("SellerUserId");

CREATE UNIQUE INDEX "IX_SavedCue_Unique_User_Cue" ON "SavedCues" ("UserId", "CueId");

CREATE INDEX "IX_SavedCues_CueId" ON "SavedCues" ("CueId");

CREATE UNIQUE INDEX "IX_Transaction_Number" ON "Transactions" ("TransactionNumber");

CREATE INDEX "IX_Transaction_Status" ON "Transactions" ("Status");

CREATE INDEX "IX_Transactions_BuyerId" ON "Transactions" ("BuyerId");

CREATE INDEX "IX_Transactions_CueId" ON "Transactions" ("CueId");

CREATE INDEX "IX_Transactions_SellerId" ON "Transactions" ("SellerId");

CREATE UNIQUE INDEX "IX_User_Email" ON "Users" ("Email");

CREATE UNIQUE INDEX "IX_User_Username" ON "Users" ("Username");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260103183000_InitialCreate', '8.0.0');

COMMIT;

